CREATE TABLE hide_rounds (id TEXT PRIMARY KEY, match_id TEXT NOT NULL REFERENCES hide_matches(id), n INTEGER NOT NULL CHECK(n IN (1,2)), hider TEXT NOT NULL REFERENCES players(id), seeker TEXT NOT NULL REFERENCES players(id), ready_a INTEGER NOT NULL DEFAULT 0, ready_b INTEGER NOT NULL DEFAULT 0, hide_at INTEGER, search_at INTEGER, hidden_spot INTEGER, found_at INTEGER, reason TEXT, score INTEGER NOT NULL DEFAULT 0, sx REAL NOT NULL DEFAULT 480, sy REAL NOT NULL DEFAULT 350, move_at INTEGER NOT NULL DEFAULT 0, move_seq INTEGER NOT NULL DEFAULT 0, inspect_at INTEGER NOT NULL DEFAULT 0, checked TEXT NOT NULL DEFAULT '[]', check_version INTEGER NOT NULL DEFAULT 0, paused_at INTEGER, UNIQUE(match_id,n));
